import { readFile, writeFile } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
const base = '/home/genie/.local/share/mikro-engine-split/experiments-g8';
const resources = JSON.parse(await readFile(`${base}/prepared-native-receipt3-resources.json`, 'utf8'));
const rows = [];
for (const binding of resources.native) {
  const command = ['/home/genie/.hermes/node/bin/node', '/home/genie/orca/workspaces/genie/mikro-engine-split/scripts/mikro/engine-experiment-runtime.mjs', '--profile', binding.profilePath, '--check'];
  const start = performance.now();
  const result = spawnSync(command[0], command.slice(1), { encoding: 'utf8', timeout: 120000 });
  const row = { id: binding.id, command, exitCode: result.status, signal: result.signal, error: result.error ? { name: result.error.name, message: result.error.message } : null, elapsedMs: performance.now() - start, stdout: result.stdout, stderr: result.stderr, modelCalls: 0 };
  rows.push(row);
  await writeFile(`${base}/native-preparation-receipt3/main-public-checks.json`, `${JSON.stringify({ schemaVersion: 1, complete: false, expected: 19, rows }, null, 2)}\n`, { mode: 0o600 });
  if (result.status !== 0 || result.error) throw new Error(`${binding.id}: actual public check failed ${result.status}`);
  const value = JSON.parse(result.stdout);
  if (value.budgetBinding.maxDepth !== 0) throw new Error(`${binding.id}: expected actual maxDepth0`);
  console.log(JSON.stringify({ id: binding.id, exitCode: result.status, maxDepth: value.budgetBinding.maxDepth, modelCalls: 0 }));
}
if (rows.length !== 19) throw new Error('exact native19 required');
await writeFile(`${base}/native-preparation-receipt3/main-public-checks.json`, `${JSON.stringify({ schemaVersion: 1, complete: true, expected: 19, rows, modelCalls: 0 }, null, 2)}\n`, { mode: 0o600 });
console.log('MAIN_NATIVE_RECEIPT3_ALL19_PUBLIC_CHECKS_EXIT=0');
